// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 val) public {
        vm.assume(user != address(0) && user != address(this));
        val = bound(val, 1, 1e18); // any positive value

        // Deploy a fresh instance to have known initial state
        c = new C();
        vm.prank(user);
        vm.deal(user, val);

        uint256 beforeTotalDistributed = c.totalDistributed();
        c.getTokens();
        uint256 afterTotalDistributed = c.totalDistributed();

        // The reference satisfies: if getTokens() was called, totalDistributed MUST increase by value
        // Buggy version leaves it unchanged after XBornID() sets it, so this fails
        assertTrue(afterTotalDistributed >= beforeTotalDistributed + 1e18);
    }
}

